// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    Reverter r;

    function setUp() public {
        c = new Reentrance();
        r = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        vm.deal(address(r), amount);
        vm.prank(address(r));
        c.addToBalance{value: amount}();

        vm.prank(address(r));
        try c.withdrawBalance() {
            // call completed: the mutant path - ETH never left c but the
            // ledger was zeroed, violating conservation.
        } catch {
            // correct path: atomic revert.
        }

        assertTrue(
            address(c).balance == amount && c.getBalance(address(r)) == amount,
            "failed withdrawal must leave contract ETH and user balance intact"
        );
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }
}
